'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var isBetween = require( '@stdlib/assert/is-between' );
var isBooleanArray = require( '@stdlib/array/base/assert/is-booleanarray' );
var isComplex128Array = require( '@stdlib/array/base/assert/is-complex128array' );
var isComplex64Array = require( '@stdlib/array/base/assert/is-complex64array' );
var isInt64Array = require( '@stdlib/assert/is-int64array' );
var isInteger = require( '@stdlib/assert/is-integer' ).isPrimitive;
var isUint64Array = require( '@stdlib/assert/is-uint64array' );
var reinterpretBoolean = require( '@stdlib/strided/base/reinterpret-boolean' );
var reinterpret128 = require( '@stdlib/strided/base/reinterpret-complex128' );
var reinterpret64 = require( '@stdlib/strided/base/reinterpret-complex64' );
var reinterpretInt64 = require( '@stdlib/strided/base/reinterpret-int64' );
var reinterpretUint64 = require( '@stdlib/strided/base/reinterpret-uint64' );
var uint64ToWords = require( '@stdlib/number/uint64/base/number2words' ).assign;
var int64ToWords = require( '@stdlib/number/int64/base/number2words' ).assign;
var signbit32 = require( '@stdlib/number/int32/base/signbit' );
var indices = require( './indices.js' );


// VARIABLES //

var TWO_63 = 9223372036854775808;  // 2^63
var TWO_64 = 18446744073709551616; // 2^64
var W = [ 0, 0 ];


// FUNCTIONS //

/**
* Tests if two arrays have equal values.
*
* @private
* @param {Collection} x - first input array
* @param {Collection} y - second input array
* @returns {boolean} boolean indicating if both arrays have equal values
*
* @example
* var x = [ 0, 0, 1, 0 ];
* var y = [ 0, 0, 1, 0 ];
*
* var out = internal( x, y );
* // returns true
*
* @example
* var x = [ 0, 0, 0, 0 ];
* var y = [ 0, 0, 1, 0 ];
*
* var out = internal( x, y );
* // returns false
*/
function internal( x, y ) {
	var i;
	for ( i = 0; i < x.length; i++ ) {
		if ( x[ i ] !== y[ i ] ) {
			return false;
		}
	}
	return true;
}

/**
* Tests if two arrays have equal values.
*
* @private
* @param {Object} x - first input array object
* @param {Object} y - second input array object
* @returns {boolean} boolean indicating if both arrays have equal values
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = arraylike2object( toAccessorArray( [ 0, 0, 1, 0 ] ) );
* var y = arraylike2object( toAccessorArray( [ 0, 0, 1, 0 ] ) );
*
* var out = accessors( x, y );
* // returns true
*
* @example
* var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
*
* var x = arraylike2object( toAccessorArray( [ 0, 0, 0, 0 ] ) );
* var y = arraylike2object( toAccessorArray( [ 0, 0, 1, 0 ] ) );
*
* var out = accessors( x, y );
* // returns false
*/
function accessors( x, y ) {
	var xdata;
	var ydata;
	var xget;
	var yget;
	var i;

	xdata = x.data;
	ydata = y.data;

	xget = x.accessors[ 0 ];
	yget = y.accessors[ 0 ];

	for ( i = 0; i < xdata.length; i++ ) {
		if ( xget( xdata, i ) !== yget( ydata, i ) ) {
			return false;
		}
	}
	return true;
}

/**
* Tests if a 64-bit unsigned integer array and a 64-bit signed integer array have equal values.
*
* ## Notes
*
* -   Both input arrays are expected to have been reinterpreted as arrays of interleaved high and low words.
* -   If the sign bit of a high word is set, the corresponding 64-bit signed integer is negative and, thus, cannot equal a 64-bit unsigned integer, even when the bit patterns are identical (e.g., `-1` and `2^64-1`).
*
* @private
* @param {Uint32Array} x - unsigned integer array reinterpreted as interleaved high and low words
* @param {Uint32Array} y - signed integer array reinterpreted as interleaved high and low words
* @returns {boolean} boolean indicating if both arrays have equal values
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
* var Int64Array = require( '@stdlib/array/int64' );
* var reinterpretUint64 = require( '@stdlib/strided/base/reinterpret-uint64' );
* var reinterpretInt64 = require( '@stdlib/strided/base/reinterpret-int64' );
*
* var x = reinterpretUint64( new Uint64Array( [ 0, 0, 1, 0 ] ), 0 );
* var y = reinterpretInt64( new Int64Array( [ 0, 0, 1, 0 ] ), 0 );
*
* var out = mixed64( x, y );
* // returns true
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
* var Int64Array = require( '@stdlib/array/int64' );
* var reinterpretUint64 = require( '@stdlib/strided/base/reinterpret-uint64' );
* var reinterpretInt64 = require( '@stdlib/strided/base/reinterpret-int64' );
*
* var x = reinterpretUint64( new Uint64Array( [ 0, 0, 1, 0 ] ), 0 );
* var y = reinterpretInt64( new Int64Array( [ 0, 0, -1, 0 ] ), 0 );
*
* var out = mixed64( x, y );
* // returns false
*/
function mixed64( x, y ) {
	var i;
	for ( i = 0; i < x.length; i += 2 ) {
		if (
			x[ i+indices.HIGH ] !== y[ i+indices.HIGH ] ||
			x[ i+indices.LOW ] !== y[ i+indices.LOW ] ||
			signbit32( y[ i+indices.HIGH ] )
		) {
			return false;
		}
	}
	return true;
}

/**
* Tests if a 64-bit integer array and an array of numeric values have equal values.
*
* ## Notes
*
* -   The 64-bit integer array is expected to have been reinterpreted as an array of interleaved high and low words.
* -   An element of the second input array is considered equal to a 64-bit integer only if the element is an integer on the interval `[min, max)` whose high and low words match those of the 64-bit integer. Splitting each element into high and low words (rather than converting each 64-bit integer to a double-precision floating-point number) avoids rounding errors for values exceeding the maximum safe integer.
*
* @private
* @param {Uint32Array} x - 64-bit integer array reinterpreted as interleaved high and low words
* @param {Object} y - second input array object
* @param {number} min - minimum value (inclusive) which can be represented by the 64-bit integer data type
* @param {number} max - maximum value (exclusive) which can be represented by the 64-bit integer data type
* @param {Function} toWords - function which splits a number into the high and low words of a 64-bit integer
* @returns {boolean} boolean indicating if both arrays have equal values
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
* var reinterpretUint64 = require( '@stdlib/strided/base/reinterpret-uint64' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
* var toWords = require( '@stdlib/number/uint64/base/number2words' ).assign;
*
* var x = reinterpretUint64( new Uint64Array( [ 0, 0, 1, 0 ] ), 0 );
* var y = arraylike2object( [ 0, 0, 1, 0 ] );
*
* var out = numeric64( x, y, 0, 18446744073709551616, toWords );
* // returns true
*
* @example
* var Int64Array = require( '@stdlib/array/int64' );
* var reinterpretInt64 = require( '@stdlib/strided/base/reinterpret-int64' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
* var toWords = require( '@stdlib/number/int64/base/number2words' ).assign;
*
* var x = reinterpretInt64( new Int64Array( [ 0, 0, -1, 0 ] ), 0 );
* var y = arraylike2object( [ 0, 0, -1, 0 ] );
*
* var out = numeric64( x, y, -9223372036854775808, 9223372036854775808, toWords );
* // returns true
*
* @example
* var Int64Array = require( '@stdlib/array/int64' );
* var reinterpretInt64 = require( '@stdlib/strided/base/reinterpret-int64' );
* var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
* var toWords = require( '@stdlib/number/int64/base/number2words' ).assign;
*
* var x = reinterpretInt64( new Int64Array( [ 0, 0, -1, 0 ] ), 0 );
* var y = arraylike2object( [ 0, 0, -2, 0 ] );
*
* var out = numeric64( x, y, -9223372036854775808, 9223372036854775808, toWords );
* // returns false
*/
function numeric64( x, y, min, max, toWords ) {
	var ydata;
	var yget;
	var v;
	var i;
	var j;

	ydata = y.data;
	yget = y.accessors[ 0 ];

	j = 0;
	for ( i = 0; i < ydata.length; i++ ) {
		v = yget( ydata, i );

		// Only integers on the interval `[min, max)` can be exactly represented as 64-bit integers...
		if ( !isInteger( v ) || !isBetween( v, min, max, 'closed', 'open' ) ) {
			return false;
		}
		// Split the value into high and low words...
		toWords( v, W, 1, 0 );
		if ( x[ j+indices.HIGH ] !== W[ 0 ] || x[ j+indices.LOW ] !== W[ 1 ] ) {
			return false;
		}
		j += 2;
	}
	return true;
}


// MAIN //

/**
* Tests if two arrays have equal values.
*
* @param {Collection} x - first input array
* @param {Collection} y - second input array
* @returns {boolean} boolean indicating if both arrays have equal values
*
* @example
* var x = [ 0, 0, 1, 0 ];
* var y = [ 0, 0, 1, 0 ];
*
* var out = hasEqualValues( x, y );
* // returns true
*
* @example
* var x = [ 0, 0, 0, 0 ];
* var y = [ 0, 0, 1, 0 ];
*
* var out = hasEqualValues( x, y );
* // returns false
*
* @example
* var Uint64Array = require( '@stdlib/array/uint64' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Uint64Array( [ 0, 0, 1, 0 ] );
* var y = new Float64Array( [ 0.0, 0.0, 1.0, 0.0 ] );
*
* var out = hasEqualValues( x, y );
* // returns true
*/
function hasEqualValues( x, y ) {
	var FLG;
	var xo;
	var yo;
	var xr;
	var yr;

	if ( x.length !== y.length ) {
		return false;
	}
	xo = arraylike2object( x );
	yo = arraylike2object( y );
	if ( xo.accessorProtocol || yo.accessorProtocol ) {
		FLG = 2;

		// If provided boolean arrays, reinterpret the arrays to avoid using accessors to access array elements...
		if ( isBooleanArray( x ) ) {
			if ( isBooleanArray( y ) ) {
				return internal( reinterpretBoolean( x, 0 ), reinterpretBoolean( y, 0 ) ); // eslint-disable-line max-len
			}
			return accessors( xo, yo );
		}
		// If provided 64-bit unsigned integer arrays, reinterpret as arrays of interleaved high and low words...
		if ( isUint64Array( x ) ) {
			if ( isUint64Array( y ) ) {
				return internal( reinterpretUint64( x, 0 ), reinterpretUint64( y, 0 ) );
			}
			if ( isInt64Array( y ) ) {
				return mixed64( reinterpretUint64( x, 0 ), reinterpretInt64( y, 0 ) );
			}
			return numeric64( reinterpretUint64( x, 0 ), yo, 0, TWO_64, uint64ToWords );
		}
		if ( isInt64Array( x ) ) {
			if ( isInt64Array( y ) ) {
				return internal( reinterpretInt64( x, 0 ), reinterpretInt64( y, 0 ) );
			}
			if ( isUint64Array( y ) ) {
				return mixed64( reinterpretUint64( y, 0 ), reinterpretInt64( x, 0 ) );
			}
			return numeric64( reinterpretInt64( x, 0 ), yo, -TWO_63, TWO_63, int64ToWords );
		}
		if ( isUint64Array( y ) ) {
			return numeric64( reinterpretUint64( y, 0 ), xo, 0, TWO_64, uint64ToWords );
		}
		if ( isInt64Array( y ) ) {
			return numeric64( reinterpretInt64( y, 0 ), xo, -TWO_63, TWO_63, int64ToWords );
		}
		// If provided a complex number array, reinterpret as a real typed array and test interleaved real and imaginary components...
		if ( isComplex128Array( x ) ) {
			xr = reinterpret128( x, 0 );
			FLG -= 1;
		} else if ( isComplex64Array( x ) ) {
			xr = reinterpret64( x, 0 );
			FLG -= 1;
		}
		if ( isComplex128Array( y ) ) {
			yr = reinterpret128( y, 0 );
			FLG -= 1;
		} else if ( isComplex64Array( y ) ) {
			yr = reinterpret64( y, 0 );
			FLG -= 1;
		}
		// TODO: Consider adding support for comparing real valued arrays with complex valued arrays...
		if ( FLG === 0 ) {
			return internal( xr, yr );
		}
		return accessors( xo, yo );
	}
	return internal( x, y );
}


// EXPORTS //

module.exports = hasEqualValues;
